#include <tunables/global>
/usr/local/bin/reportd {
  #include <abstractions/base>
  capability net_bind_service,
  network inet stream,
  /etc/reportd/** r,
  /var/lib/reportd/** rw,
  /usr/local/bin/reportd mr,
  deny /etc/shadow r,
}
